<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { fetchWorkReportDay } from '@/api/workshopReporting'
import { useAuthStore } from '@/stores/auth'
import WorkReportDeleteDialog from '@/components/workshop/WorkReportDeleteDialog.vue'
import type { WorkReport } from '@/types/workshopReporting'
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const reports = ref<WorkReport[]>([]); const loading = ref(false); const page = ref(1); const pageSize = ref(20); const total = ref(0); const errorMessage = ref('')
const canEdit = computed(() => auth.user?.is_superuser || auth.hasPermission('workshop_reporting.change_workreport'))
const deleteOpen = ref(false), deletingReport = ref<WorkReport | null>(null)
function openDelete(report: WorkReport) { deletingReport.value = report; deleteOpen.value = true }
async function deleted() { if (reports.value.length === 1 && page.value > 1) page.value -= 1; await load() }
const scheduleProductId = computed(() => String(route.query.schedule_product_id || ''))
const planQuery = computed(() => scheduleProductId.value ? { schedule_product_id: scheduleProductId.value } : {})
async function load() { loading.value = true; try { const result = await fetchWorkReportDay(String(route.params.productionDate), { page: page.value, page_size: pageSize.value, schedule_product_id: scheduleProductId.value || undefined }); reports.value = result.data; total.value = result.meta.total; errorMessage.value = '' } catch (error) { errorMessage.value = (error as { response?: { data?: { error?: { message?: string } } } })?.response?.data?.error?.message || '当日报工明细加载失败。' } finally { loading.value = false } }
onMounted(load)
</script>
<template><section class="wr-page" data-testid="work-report-day-detail"><header class="wr-heading"><div><h1>{{ route.params.productionDate }} 报工明细</h1><p>保留每次保存的报工编号、产品、员工和工价快照</p></div><ElButton @click="router.push({ name: 'work-report-days', query: planQuery })">返回汇总</ElButton></header><ElAlert v-if="scheduleProductId" class="wr-context-alert" type="info" :closable="false" show-icon title="已按当前内部作业计划筛选" /><ElAlert v-if="errorMessage" type="error" :closable="false" show-icon :title="errorMessage" /><div v-else class="wr-report-stack" v-loading="loading"><section v-for="report in reports" :key="report.id" class="wr-card"><div class="wr-card-title"><div><h2>{{ report.report_number }}</h2><p>{{ report.production_task.task_number }} · {{ report.product.name }}（{{ report.product.number }}） · {{ report.workshop.name }} · 录入人 {{ report.recorder }} · 最后修改 {{ report.updated_by }}</p></div><div><strong>¥{{ report.total_amount }}</strong><ElButton v-if="canEdit" link type="primary" @click="router.push({ name: 'work-report-edit', params: { reportId: report.id } })">编辑</ElButton><ElButton v-if="report.can_delete" link type="danger" @click="openDelete(report)">删除</ElButton></div></div><ElTable :data="report.lines" border><ElTableColumn prop="employee_name" label="员工" width="130" /><ElTableColumn label="生产线" width="90"><template #default="{ row }">{{ row.production_line ? `${row.production_line}线` : '—' }}</template></ElTableColumn><ElTableColumn prop="craft_name" label="工艺" width="130" /><ElTableColumn prop="operation_name" label="工序" min-width="150" /><ElTableColumn prop="display_name" label="名称 / 部位" min-width="170" /><ElTableColumn prop="quantity" label="完成次数" width="130" /><ElTableColumn prop="unit_price" label="工价" width="110" /><ElTableColumn prop="amount" label="金额" width="120" /></ElTable></section><ElEmpty v-if="!loading && !reports.length" description="当日暂无报工明细" /></div><footer class="wr-pagination"><span>共 {{ total }} 次保存</span><ElPagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" layout="sizes, prev, pager, next" @current-change="load" @size-change="page = 1; load()" /></footer><WorkReportDeleteDialog v-model="deleteOpen" :report="deletingReport" @deleted="deleted" /></section></template>
<style lang="scss">@use '@/styles/workshopReporting.scss';</style>
